// Emits the Go artifact: zz_categories.gen.go for package `domain`.
//
// Design: the generated file is SELF-CONTAINED and import-free. It declares the
// catalog entry type, the ordered catalog slice, and the user-category default
// style. Lookup goes by linear scan over the ordered slice — the catalog is 40
// entries, and a single source of the data in the file beats a duplicated
// slug→entry map. The payments context (schema/API ticket) builds its domain
// types on top of these symbols.

const HEADER = `// Code generated by tools/payment-categories/generate.mjs from catalog.json. DO NOT EDIT.
//
// zz_categories.gen.go — сгенерировано из tools/payment-categories/catalog.json.
// НЕ редактировать вручную. Чтобы регенерировать:
//
//\tcd tools/payment-categories && node generate.mjs
//
// (или из корня монорепо: make categories-gen)
//
// Самодостаточный модуль без импортов: дефолтный каталог категорий платежей
// (слаг для ссылки из БД, название, иконка и цвет подложки из Figma-набора)
// и дефолтный внешний вид пользовательской категории. Категория нейтральна к
// направлению: доход/расход выбирается на платеже, а не в каталоге.
`;

function goStr(s) {
  return JSON.stringify(s);
}

function emitEntry(cat) {
  return `\t{Slug: ${goStr(cat.slug)}, Label: ${goStr(cat.label)}, Icon: ${goStr(cat.icon)}, Color: ${goStr(cat.color)}},`;
}

export function emitGo(catalog) {
  const entries = catalog.categories.map(emitEntry).join('\n');
  const userDefault = catalog.userCategoryDefault;

  return `${HEADER}
package domain

// CategoryCatalogEntry — запись дефолтного каталога категорий платежей.
// Slug — каноническая ссылка из БД; Icon — имя SVG-ассета из Figma-набора
// Icon/Bold (apps/frontend/shared/assets/icons); Color — HEX цвета подложки
// иконки.
type CategoryCatalogEntry struct {
\tSlug  string
\tLabel string
\tIcon  string
\tColor string
}

// UserCategoryStyle — внешний вид пользовательской категории: у своих
// категорий одна дефолтная иконка (решение карты «Платежи и операции» №4).
type UserCategoryStyle struct {
\tIcon  string
\tColor string
}

// defaultCategories — дефолтный каталог в каноническом порядке (порядок UI
// из Figma). Общий для всех вызовов: не мутировать.
var defaultCategories = []CategoryCatalogEntry{
${entries}
}

// userCategoryDefaultStyle — дефолтный внешний вид пользовательской категории.
var userCategoryDefaultStyle = UserCategoryStyle{Icon: ${goStr(userDefault.icon)}, Color: ${goStr(userDefault.color)}}

// DefaultCategories возвращает дефолтный каталог категорий в каноническом
// порядке UI. Возвращённый слайс общий для всех вызовов — не мутировать.
func DefaultCategories() []CategoryCatalogEntry {
\treturn defaultCategories
}

// CategoryBySlug ищет запись дефолтного каталога по слагу.
func CategoryBySlug(slug string) (CategoryCatalogEntry, bool) {
\tfor _, entry := range defaultCategories {
\t\tif entry.Slug == slug {
\t\t\treturn entry, true
\t\t}
\t}
\treturn CategoryCatalogEntry{}, false
}

// IsValidDefaultCategorySlug сообщает, входит ли слаг в дефолтный каталог.
func IsValidDefaultCategorySlug(slug string) bool {
\t_, ok := CategoryBySlug(slug)
\treturn ok
}

// UserCategoryDefaultStyle возвращает дефолтный внешний вид пользовательской
// категории (иконка и цвет подложки).
func UserCategoryDefaultStyle() UserCategoryStyle {
\treturn userCategoryDefaultStyle
}
`;
}
